effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec2 uv = acScreenNorm*scale;
    float t = acTime*speed;
    float v = sin(uv.x+t) + sin(uv.y+t) + sin(uv.x+uv.y+t)
            + sin(length(uv-vec2(scale*0.5))+t);
    v *= 0.25;
    vec3 col = 0.5 + 0.5*cos(6.2831*(v + vec3(0.0,0.33,0.67)));
    vec4 res;
    if(blendMode==1) res = vec4((src.rgb/max(src.a,0.001))*col,1.0)*src.a;
    else if(blendMode==2) res = vec4(1.0-(1.0-src.rgb/max(src.a,0.001))*(1.0-col),1.0)*src.a;
    else res = vec4(col,1.0);
    gl_FragColor = mix(src, res, alpha);
}
